fn create_row(n: u8) -> Vec<u8> {
    (0..n).collect() // Collects numbers from 0 to n-1 into a vector
}

fn indices(n: u8) -> Vec<Vec<u8>> {
    vec![create_row(n)] // Wraps the result of create_row in a vector
}

fn main() {
    // Example usage
    let n = 5;
    let row = create_row(n);
    let grid = indices(n);
    
    println!("{:?}", row); // Output: [0, 1, 2, 3, 4]
    println!("{:?}", grid); // Output: [[0, 1, 2, 3, 4]]
}